#include <iostream>
#include <string>
#include <vector>

class Monster
{
public:
    enum class Type { goblin, orc, dragon };

    Monster(Type type, std::string name, int hp)
        : m_id{ ++s_created }, m_type{ type }, m_name{ std::move(name) }, m_hp{ hp }
    {
        ++s_alive;
        std::cout << "Monster #" << m_id << " (" << m_name << ") appears\n";
    }

    ~Monster()
    {
        --s_alive;
        std::cout << "Monster #" << m_id << " was destroyed\n";
    }

    static int alive() { return s_alive; }
    // TODO: static Monster createRandom()

private:
    static inline int s_created{ 0 };
    static inline int s_alive{ 0 };
    int m_id{};
    Type m_type{};
    std::string m_name{};
    int m_hp{};
};

int main()
{
    Monster boss{ Monster::Type::dragon, "Smaug", 500 };
    {
        Monster minion{ Monster::Type::goblin, "Snik", 20 };
        std::cout << "Alive: " << Monster::alive() << '\n';
    }
    std::cout << "Alive: " << Monster::alive() << '\n';
    // TODO: a vector of monsters; predict the messages before you run it
    return 0;
}
